*, *::before, *::after {
  box-sizing: border-box;
}

.box {
  width: 300px;
  padding: 20px;
  border: 5px solid black;
}
/* border-box: renders exactly 300px wide
   content-box: would render 350px */

#nav .item { }        /* 1 ID, 1 class → strong */
.menu li.selected {}   /* 2 classes, 1 element */
div {}                 /* weakest tier */

/* Modern layering beats specificity games: */
@layer base, components, utilities;
@layer components { .btn { color: blue; } }
@layer utilities  { .text-red { color: red; } } /* wins regardless */

:root { font-size: 100%; } /* 16px base */

.card {
  padding: 1.5rem;            /* scales with root */
  border: 1px solid #ddd;     /* crisp hairline */
  max-width: 40ch;            /* readable line length */
}

.badge {
  font-size: 0.75em;          /* relative to parent text */
  padding-inline: 0.75em;     /* grows with its own font */
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
